// Package api holds the generated OpenAPI models, the route table and the
// bundled spec. Each tag's server interface lives in its own <tag>api
// subpackage. Everything except this file is generated by scripts/gen.sh.
package api

import (
	_ "embed"
	"slices"
	"strings"
)

// Spec is contract/dist/openapi.json, the bundled OpenAPI document.
//
//go:embed openapi.json
var Spec []byte

// Route is one operation of the contract.
type Route struct {
	Method      string
	Path        string // template with BasePath, for example /v1/agents/{agent_name}
	OperationID string
	Tag         string
	// Stream is true for server-sent event streams (x-stream or text/event-stream).
	Stream bool
	// WebSocket is true for operations that upgrade (x-websocket), such as terminals.
	WebSocket bool
	// Scope is the one scope a bearer token needs, from bearerAuth in the
	// operation's security. Empty means the operation takes no token.
	Scope string
	// Public is true when the operation's security admits anonymous callers.
	Public bool
}

// ScopeLevels orders the scope levels: a level covers every level before it.
var ScopeLevels = []string{"read", "write", "admin"}

// Covers reports whether a held scope satisfies a needed one: same group,
// same or higher level (admin covers write and read, write covers read).
func Covers(held, need string) bool {
	hg, hl, ok1 := strings.Cut(held, ":")
	ng, nl, ok2 := strings.Cut(need, ":")
	if !ok1 || !ok2 || hg != ng {
		return false
	}
	hi, ni := slices.Index(ScopeLevels, hl), slices.Index(ScopeLevels, nl)
	return hi >= 0 && ni >= 0 && hi >= ni
}

// AllScopes is the admin scope of every group the contract names, sorted.
// It covers every operation that takes a token.
func AllScopes() []string {
	seen := map[string]bool{}
	var out []string
	for _, r := range Routes {
		if g, _, ok := strings.Cut(r.Scope, ":"); ok && !seen[g] {
			seen[g] = true
			out = append(out, g+":admin")
		}
	}
	slices.Sort(out)
	return out
}

// Match finds the route for a method and a concrete path. Literal segments
// win over parameters, as in net/http.
func Match(method, path string) (Route, bool) {
	var best Route
	bestScore := -1
	for _, r := range Routes {
		if r.Method != method {
			continue
		}
		if score, ok := matchPath(r.Path, path); ok && score > bestScore {
			best, bestScore = r, score
		}
	}
	return best, bestScore >= 0
}

// matchPath returns the number of literal segments matched.
func matchPath(template, path string) (int, bool) {
	want := strings.Split(strings.Trim(template, "/"), "/")
	got := strings.Split(strings.Trim(path, "/"), "/")
	if len(want) != len(got) {
		return 0, false
	}
	literal := 0
	for i, w := range want {
		switch {
		case strings.HasPrefix(w, "{") && strings.HasSuffix(w, "}"):
			if got[i] == "" {
				return 0, false
			}
		case w == got[i]:
			literal++
		default:
			return 0, false
		}
	}
	return literal, true
}
